import{_ as a,o as t,c as r,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Completed-house purchase source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/48-completed-house-purchase-profile.md","filePath":"reference/48-completed-house-purchase-profile.md","lastUpdated":1788614098000}'),i={name:"reference/48-completed-house-purchase-profile.md"};function s(n,e,c,d,h,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="completed-house-purchase-source-profile" tabindex="-1">Completed-house purchase source profile <a class="header-anchor" href="#completed-house-purchase-source-profile" aria-label="Permalink to &quot;Completed-house purchase source profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The <code>house_purchase</code> activity uses B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter XII, “Buying Houses,” internal printed page 54 (physical PDF page 58 in the inspected 2020 Chistabo derivative). Raman explicitly includes both new and old completed houses. This is not the election for buying land for construction, starting building work, moving into a rental, or performing Gruhapravesha.</p><p>Rama Daivajna&#39;s <em>Muhurta Chintamani</em>, Nakshatra-prakarana verse 16, printed pages 33–34 (OCR lines 2336–2350), was inspected as an independent buyer-side authority. Its generic purchase Nakshatras are materially different. The implementation therefore links that claim for comparison but does not combine the two formulas or let the generic rule override the house-specific passage.</p><h2 id="automated-crosswalk" tabindex="-1">Automated crosswalk <a class="header-anchor" href="#automated-crosswalk" aria-label="Permalink to &quot;Automated crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Product rule</th></tr></thead><tbody><tr><td>Nanda Tithis are favourable</td><td>Admit Tithi numbers 1, 6 and 11</td></tr><tr><td>New and old houses may be purchased Thursday and Friday</td><td>Admit <code>Guruvaram</code> and <code>Shukravaram</code></td></tr><tr><td>Eight auspicious constellations</td><td>Admit Mrigashira, Ashlesha, Magha, Purva Phalguni, Vishakha, Moola, Punarvasu and Revati</td></tr><tr><td>Five signs are “best”</td><td>Prefer, but do not require, Vrishabha, Mithuna, Simha, Tula and Vrischika Lagnas</td></tr></tbody></table><p>“Best” is implemented as a score bonus rather than an exclusion. This avoids turning a textual preference into an unsupported hard prohibition.</p><h2 id="practitioner-and-practical-checks" tabindex="-1">Practitioner and practical checks <a class="header-anchor" href="#practitioner-and-practical-checks" aria-label="Permalink to &quot;Practitioner and practical checks&quot;">​</a></h2><p>The Drik browser post-screen rejects Mangala in Lagna at any sampled state (the window edges and both sides of every known interior Drik Lagna transition). Keeping malefics out of the 7th remains a qualitative practitioner check, so unresolved review still caps the result below <code>Excellent</code>. Python/MCP retain both clauses as manual wording because they do not call the chart service. See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>.</p><p>Legal title, structural inspection, finance affordability and qualified contract advice always take precedence over electional timing. The profile does not predict property quality, ownership security or investment return.</p>',10)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
